-- Café y Ensalada conservan el precio histórico, distinto al precio actual.

-- Saldo inicial más ventas = stock actual.
SELECT i.product_id, i.order_id, -i.quantity, 'sale', o.created_at
FROM order_items i JOIN orders o ON o.id = i.order_id;

